from lmstudio import Plugin

class LocalLLMPlugin(Plugin):
    def act(self, context: dict) -> dict:
        return {
            "tool": "local_llm",
            "content": "This is a custom plugin for local LLMs."
        }

    def toolDefinition(self):
        return {
            "name": "local_llm",
            "description": "Interact with local LLMs",
            "parameters": {}
        }
